// ─── PARSER ───────────────────────────────────────────────────────────────
// Expands each compact line into a full day object. Verse text is merged in
// from DEVOTIONAL_VERSES (data/devotional-verses.js), keyed by the reference
// string, when that file is loaded.
var DEVOTIONAL = (function () {
  var verses = (typeof DEVOTIONAL_VERSES !== 'undefined') ? DEVOTIONAL_VERSES : {};
  var list = [];

  DEVOTIONAL_RAW.forEach(function (line, index) {
    var f = line.split('|');
    if (f.length < 15) {
      if (typeof console !== 'undefined') {
        console.warn('Devotional line ' + (index + 1) + ' is malformed (' + f.length + ' fields).');
      }
      return;
    }
    var day = parseInt(f[0], 10);
    var ref = f[3];
    list.push({
      day: day,
      topic: f[1],
      topicMg: f[2],
      ref: ref,
      verse: verses[ref] || '',
      idea: f[4],
      ideaMg: f[5],
      words: [
        { word: f[6], malagasy: f[7], example: f[8] },
        { word: f[9], malagasy: f[10], example: f[11] },
        { word: f[12], malagasy: f[13], example: f[14] },
      ],
      month: monthForDay(day),
    });
  });

  function monthForDay(day) {
    var acc = 0;
    for (var i = 0; i < DEVOTIONAL_MONTHS.length; i++) {
      acc += DEVOTIONAL_MONTHS[i].days;
      if (day <= acc) return DEVOTIONAL_MONTHS[i];
    }
    return DEVOTIONAL_MONTHS[DEVOTIONAL_MONTHS.length - 1];
  }

  return list;
})();
